        "type": "paragraph",
        "text": "تظل مواسير التغذية معرضة لضغط المياه طوال الوقت، ولذلك قد يستمر التسرب منها حتى عند عدم استخدام الصنابير، ويمكن ملاحظة المشكلة من خلال تغير قراءة العداد أو ضعف الضغط أو سماع صوت حركة المياه داخل الجدران."
