        "text": "قد تتسرب المياه من جسم الخزان بسبب الشقوق أو تلف طبقة العزل، وقد يكون الخلل في العوامة أو المواسير والوصلات المحيطة به، ولذلك يجب فحص الخزان ومكوناته قبل تحديد طريقة المعالجة."
