        "type": "paragraph",
        "text": "تُراجع المناطق الموجودة أسفل الأحواض وحول السخانات والغسالات والخلاطات، كما يجب فحص وصلات التغذية والسيفونات بحثًا عن قطرات أو ترسبات أو آثار رطوبة."
