            "type": "paragraph",
            "text": "يمكن تطبيقه في بعض الحالات بعد التأكد من ثبات البلاط وتنظيفه وتجهيزه واختبار الالتصاق. أما البلاط المفكك أو الذي يحتوي على فراغات ورطوبة فيحتاج إلى معالجة قبل الرش."
